import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"Eramaker 源码分析","description":"","frontmatter":{},"headers":[],"relativePath":"development/EraMaker.md","filePath":"development/EraMaker.md"}`),a={name:`development/EraMaker.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="eramaker-源码分析" tabindex="-1">Eramaker 源码分析 <a class="header-anchor" href="#eramaker-源码分析" aria-label="Permalink to “Eramaker 源码分析”">​</a></h1><blockquote><p><strong>说明</strong>：本仓库的只读参考工程 <code>.ref/Emuera/</code> 只包含 <strong>Emuera</strong> 的源码，并不包含 Eramaker 的源码。因此本文不是在“读 EraMaker 的代码”，而是从 <strong>Emuera 的兼容层、配置开关与官方文档</strong>出发，反推 EraMaker 的架构与行为。文中的推断部分已明确标注。</p></blockquote><h2 id="eramaker-的定位" tabindex="-1">EraMaker 的定位 <a class="header-anchor" href="#eramaker-的定位" aria-label="Permalink to “EraMaker 的定位”">​</a></h2><p>EraMaker 是 Era 系列游戏最早的引擎。它确立了用 <code>CSV</code> 描述数据、用 <code>ERB</code> 编写脚本的基本范式，今天我们在 Emuera 里用到的大部分概念——函数、变量、<code>PRINT</code> 命令、固定的游戏流程——都能追溯到它。</p><p>它后来停止维护，功能与兼容性上的局限，正是 Emuera 诞生的原因。</p><h2 id="从-兼容开关-看-eramaker" tabindex="-1">从“兼容开关”看 EraMaker <a class="header-anchor" href="#从-兼容开关-看-eramaker" aria-label="Permalink to “从“兼容开关”看 EraMaker”">​</a></h2><p>Emuera 为了运行老脚本，保留了一批兼容性开关（见<a href="./../reference/Config_File.html#兼容性开关">Config 文件参考</a>）。<strong>每一个开关，本质上都是在描述 EraMaker 当年的行为</strong>：</p><table tabindex="0"><thead><tr><th>兼容性开关</th><th>反推出的 EraMaker 行为</th></tr></thead><tbody><tr><td><code>擬似変数RANDの仕様をeramakerに合わせる</code></td><td><code>RAND</code> 使用 0～32767 的随机数、<code>X</code> 为 0 时返回 0、且存在偏差</td></tr><tr><td><code>ver1739以前の非ボタン折り返しを再現する</code></td><td>按钮折行规则与后来的版本不同</td></tr><tr><td><code>TIMESの計算をeramakerにあわせる</code></td><td><code>TIMES</code> 的计数方式不同</td></tr><tr><td><code>SPキャラを使用する</code></td><td><code>CFLAG:0</code> 非零的角色是特殊角色，必须用 <code>ADDSPCHARA</code> 注册</td></tr><tr><td><code>CALLNAMEが空文字列の時にNAMEを代入する</code></td><td>引用空的 <code>CALLNAME</code> 时返回 <code>NAME</code></td></tr><tr><td><code>セーブデータをsavフォルダ内に作成する</code></td><td>存档位置与后来不同</td></tr><tr><td><code>ユーザー関数の全ての引数の省略を許可する</code></td><td>参数省略规则更宽松</td></tr></tbody></table><p>更系统的差异清单，可以看<a href="./../translation/Difference.html">与 Eramaker 的差异</a>——那篇文档里的每一条，几乎都对应 EraMaker 的一个具体行为。</p><h2 id="架构反推" tabindex="-1">架构反推 <a class="header-anchor" href="#架构反推" aria-label="Permalink to “架构反推”">​</a></h2><p>结合上表与<a href="./../translation/Flow.html">程序流程</a>，可以大致还原 EraMaker 的架构：</p><h3 id="_1-解释执行-而非编译" tabindex="-1">1. 解释执行，而非编译 <a class="header-anchor" href="#_1-解释执行-而非编译" aria-label="Permalink to “1. 解释执行，而非编译”">​</a></h3><p>EraMaker 直接逐行解释 <code>ERB</code>。这与 Emuera 有本质区别：Emuera 会先把脚本解析成 <code>LogicalLine</code> 对象树（见 <a href="./Emuera.html#从-erb-到执行">Emuera 源码分析</a>），而 EraMaker 更接近“读到一行、解析一行、执行一行”。</p><h3 id="_2-单一全局变量表" tabindex="-1">2. 单一全局变量表 <a class="header-anchor" href="#_2-单一全局变量表" aria-label="Permalink to “2. 单一全局变量表”">​</a></h3><p>EraMaker 的变量数量是<strong>固定</strong>的：<code>A</code>～<code>Z</code>、<code>FLAG</code>、<code>CFLAG</code>、<code>ABL</code>、<code>TALENT</code>……数组大小由引擎写死，脚本无法定义新变量。这正是 Emuera 引入 <code>#DIM</code> / <code>#DIMS</code> 的原因。</p><h3 id="_3-全局函数表-按名字调用" tabindex="-1">3. 全局函数表，按名字调用 <a class="header-anchor" href="#_3-全局函数表-按名字调用" aria-label="Permalink to “3. 全局函数表，按名字调用”">​</a></h3><p><code>@函数名</code> 定义、<code>CALL</code> / <code>JUMP</code> / <code>GOTO</code> 调用的模型一脉相承。EraMaker 没有私有变量、没有头文件、没有宏，一切都在一个扁平的命名空间里。</p><h3 id="_4-固定流程" tabindex="-1">4. 固定流程 <a class="header-anchor" href="#_4-固定流程" aria-label="Permalink to “4. 固定流程”">​</a></h3><p>从 <code>@EVENTFIRST</code>、<code>@SHOW_SHOP</code> 到 <code>@EVENTCOM</code>、<code>@EVENTEND</code>，这套由引擎在特定时机自动调用的“框架函数”，是 EraMaker 定下的规矩。Emuera 完整继承并扩展了它。</p><h3 id="_5-csv-驱动" tabindex="-1">5. CSV 驱动 <a class="header-anchor" href="#_5-csv-驱动" aria-label="Permalink to “5. CSV 驱动”">​</a></h3><p><code>GameBase.csv</code>、<code>Str.csv</code>、<code>CharaXX.csv</code>、<code>Abl.csv</code>……数据与逻辑分离的设计也来自 EraMaker，格式至今基本未变。</p><h2 id="eramaker-的局限" tabindex="-1">EraMaker 的局限 <a class="header-anchor" href="#eramaker-的局限" aria-label="Permalink to “EraMaker 的局限”">​</a></h2><p>从 Emuera 的修正清单可以清楚看到它当年的问题：</p><ul><li>数组最后一个元素会破坏存档；</li><li>单目运算符 <code>-</code> 的异常（<code>-100 &lt; 0</code> 为假）；</li><li>文件最后一行不被读取；</li><li>数组越界被静默忽略；</li><li>函数名可以使用任意符号；</li><li>……</li></ul><p>这些在<a href="./../translation/Difference.html">与 Eramaker 的差异</a>中都有逐条说明。</p><h2 id="如何进一步研究" tabindex="-1">如何进一步研究 <a class="header-anchor" href="#如何进一步研究" aria-label="Permalink to “如何进一步研究”">​</a></h2><p>虽然源码不在本仓库，仍有几条路可以走：</p><ol><li><strong>读 Emuera 的兼容代码</strong>：<code>Config</code> 里与 <code>eramaker</code> 相关的分支，本身就是对老行为的说明书；</li><li><strong>读官方文档的差异页</strong>：<a href="./../translation/Difference.html">与 Eramaker 的差异</a>；</li><li><strong>对照历史版本</strong>：Emuera 的更新履历里，很多条目都是在“修正与 EraMaker 的差异”；</li><li><strong>运行老脚本对照</strong>：开启/关闭兼容开关，观察行为差异。</li></ol><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li><a href="./Emuera.html">Emuera 源码分析</a></li><li><a href="./../translation/Difference.html">与 Eramaker 的差异</a></li><li><a href="./../translation/Flow.html">程序流程</a></li><li><a href="./../guide/History.html">Era 系列历史</a></li></ul>`,30)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};